#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: scytale theme picker.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}"
THEME_FILE="$CONFIG_DIR/starship-theme"
LAYOUT_FILE="$CONFIG_DIR/starship-layout"

FAMILIES=(everforest catppuccin gruvbox nord tokyonight monokai)
FAMILY_LABELS=(
  "Everforest    浅色 light / 深色 dark"
  "Catppuccin    latte / frappe / macchiato / mocha"
  "Gruvbox       浅色 light / 深色 dark"
  "Nord          只有深色（light/dark/auto 相同）"
  "Tokyo Night   day / night / storm / moon"
  "Monokai       只有深色"
)
LAYOUTS=(powerline color plain)
LAYOUT_LABELS=(
  "powerline   色块 + 箭头（默认）"
  "color       彩色文字 + 分隔符"
  "plain       无彩色 + 分隔符"
)
SEP_CHARS=("·" "│" "・" "❯" "|")
SEP_LABELS=(
  "·   中点（默认，最轻）"
  "│   竖线（分区感）"
  "・  全角点（更宽）"
  "❯   箭头（方向感）"
  "|   ASCII 竖线（兼容性最好）"
)

CHOICE_INDEX=0

# 读取当前选择，任何失败都退回默认值
CURRENT_THEME="$(cat "$THEME_FILE" 2>/dev/null || echo 'everforest auto')"
family="${CURRENT_THEME%% *}"
mode="${CURRENT_THEME#* }"
layout="$(cat "$LAYOUT_FILE" 2>/dev/null || echo powerline)"

# 从 color 布局里读出当前分隔符
detect_separator() {
  python3 - "$REPO/starship/layouts/color.toml" <<'PY' 2>/dev/null || printf '·'
import re, sys, pathlib
text = pathlib.Path(sys.argv[1]).read_text()
m = re.search(r'^\(\[(.*?)\]\(fg:color_text\)\[', text, re.M)
print(m.group(1) if m else '·')
PY
}
sep="$(detect_separator)"

# choose "问题" label... ：编号菜单，结果放进 CHOICE_INDEX
choose() {
  local title="$1" reply i
  shift
  local -a items=("$@")
  for i in "${!items[@]}"; do
    printf '  %s%2d)%s %s\n' "$BLUE" "$((i + 1))" "$RESET" "${items[$i]}"
  done
  while :; do
    printf '  %s? %s%s ' "$YELLOW" "$title" "$RESET"
    read -r reply || return 1
    if [[ "$reply" =~ ^[0-9]+$ ]] && (( reply >= 1 && reply <= ${#items[@]} )); then
      CHOICE_INDEX=$((reply - 1))
      return 0
    fi
    warn "请输入 1-${#items[@]}"
  done
}

# 在仓库脚本的上下文里执行 scytale-theme / scytale-layout
run_zsh() {
  zsh -c "source \"$REPO/zsh/starship-theme.zsh\" >/dev/null 2>&1; $1"
}

# 条件分隔符只出现在 color / plain 两个布局里：
#   color: ([<sep>](fg:color_text)[$module](...))
#   plain: (<sep>$module)
apply_separator() {
  python3 - "$REPO/starship/layouts/color.toml" "$REPO/starship/layouts/plain.toml" "$1" <<'PY'
import pathlib, re, sys
color, plain, sep = sys.argv[1], sys.argv[2], sys.argv[3]
c = pathlib.Path(color)
p = pathlib.Path(plain)
c_text, n_color = re.subn(
    r'^\(\[.*?\]\(fg:color_text\)\[',
    lambda m: '([' + sep + '](fg:color_text)[',
    c.read_text(), flags=re.M)
p_text, n_plain = re.subn(
    r'^\((.*?)(\$.*)$',
    lambda m: '(' + sep + m.group(2),
    p.read_text(), flags=re.M)
c.write_text(c_text)
p.write_text(p_text)
print(f"  color: {n_color} 处, plain: {n_plain} 处")
PY
}

invalid_sep() {
  local s="$1"
  [[ -z "$s" || ${#s} -gt 3 ]] && return 0
  [[ "$s" == *[[:space:]]* ]] && return 0
  [[ "$s" == *'['* || "$s" == *']'* || "$s" == *'('* || "$s" == *')'* ]] && return 0
  [[ "$s" == *'"'* || "$s" == *'\'* ]] && return 0
  return 1
}

_clear
printf '\n%s%s  Scytale 主题向导%s\n' "$BOLD" "$BLUE" "$RESET"
printf '%s  %s 步 · 配色 / 布局 / 分隔符%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
printf '  Ctrl-C 可随时退出；每一步会立即写入 ~/.config。\n  %s重跑时会记住当前选择。%s\n' "$DIM" "$RESET"
pause "开始？"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "环境自检"
say "向导会直接调用仓库里的 zsh 脚本，并写入 ~/.config/starship.toml。"

missing=0
for cmd in starship zsh python3; do
  if command -v "$cmd" >/dev/null 2>&1; then
    step "找到 $cmd"
  else
    warn "缺少 $cmd"
    missing=1
  fi
done

if [[ ! -f "$CONFIG_DIR/starship.toml" ]]; then
  warn "还没安装：找不到 $CONFIG_DIR/starship.toml"
  if confirm "现在运行 ./install.sh 吗？"; then
    ( cd "$REPO" && ./install.sh )
  else
    warn "未安装时切换不会生效。"
    confirm "仍然继续？" || exit 1
  fi
else
  step "已安装：$CONFIG_DIR/starship.toml"
fi

if (( missing )); then
  warn "依赖不齐，先补齐后重跑本向导。"
  exit 1
fi

pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "选择配色"
say "当前：$family $mode"
note "选家族，再选模式；auto 会跟随 macOS 深浅色。"
choose "选择主题家族" "${FAMILY_LABELS[@]}"
family="${FAMILIES[$CHOICE_INDEX]}"

case "$family" in
  everforest)
    modes=(auto light dark)
    mode_labels=("auto（跟随 macOS）" "light" "dark") ;;
  catppuccin)
    modes=(auto light dark latte frappe macchiato mocha)
    mode_labels=("auto（latte/mocha）" "light（= latte）" "dark（= mocha）" "latte" "frappe" "macchiato" "mocha") ;;
  gruvbox)
    modes=(auto light dark)
    mode_labels=("auto（跟随 macOS）" "light" "dark") ;;
  nord)
    modes=(auto)
    mode_labels=("auto（Nord 只有深色）") ;;
  tokyonight)
    modes=(auto light dark day night storm moon)
    mode_labels=("auto（day/night）" "light（= day）" "dark（= night）" "day" "night" "storm" "moon") ;;
  monokai)
    modes=(auto)
    mode_labels=("auto（Monokai 只有深色）") ;;
esac

choose "选择模式" "${mode_labels[@]}"
mode="${modes[$CHOICE_INDEX]}"
run_zsh "scytale-theme '$family' '$mode'"
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "选择布局"
say "当前：$layout"
choose "选择布局" "${LAYOUT_LABELS[@]}"
layout="${LAYOUTS[$CHOICE_INDEX]}"
run_zsh "scytale-layout '$layout'"
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "选择分隔符"

if [[ "$layout" == "powerline" ]]; then
  say "可用分隔符："
  for i in "${!SEP_CHARS[@]}"; do
    printf '  %s%2d)%s %s\n' "$BLUE" "$((i + 1))" "$RESET" "${SEP_LABELS[$i]}"
  done
  note "当前：$sep"
  warn "powerline 用箭头连接模块，不使用文字分隔符；上面的选项仅作参考。"
else
  choose "选择分隔符，或用最后一项自定义" "${SEP_LABELS[@]}" "自定义"
  if (( CHOICE_INDEX < ${#SEP_CHARS[@]} )); then
    sep="${SEP_CHARS[$CHOICE_INDEX]}"
  else
    while :; do
      ask SEP_CUSTOM "输入分隔符（1-3 个字符）："
      sep="$SEP_CUSTOM"
      invalid_sep "$sep" || break
      warn "不能为空，且不能包含空格、方括号、圆括号、引号或反斜杠。"
    done
  fi
  say "将把分隔符「${sep}」写入 starship/layouts/color.toml 与 plain.toml。"
  note "这两个文件在仓库里，写入后工作区会产生 diff。"
  if confirm "写入并重新渲染当前布局？"; then
    apply_separator "$sep"
    run_zsh "scytale-layout reload"
  else
    warn "已取消，分隔符保持不变。"
    sep="$(detect_separator)"
  fi
fi
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "预览"
say "当前配置："
note "  配色：$(cat "$THEME_FILE" 2>/dev/null || echo "$family $mode")"
note "  布局：$(cat "$LAYOUT_FILE" 2>/dev/null || echo "$layout")"
if [[ "$layout" != "powerline" ]]; then
  note "  分隔符：$sep"
fi
say "提示符预览："
preview="$(STARSHIP_SHELL=bash STARSHIP_CONFIG="$CONFIG_DIR/starship.toml" starship prompt 2>/dev/null | sed 's/\\\[//g; s/\\\]//g')"
if [[ -n "$preview" ]]; then
  printf '\n  %s\n' "$preview"
else
  warn "预览失败，不影响已应用的配置。"
fi
pause

finish
printf '\n'
note "配色：$family $mode"
note "布局：$layout"
[[ "$layout" != "powerline" ]] && note "分隔符：$sep"
say "新开终端或执行 exec zsh 确认最终效果。"

}

run_wizard "$@"; exit
